# Cache for base64-encoded SVGs
_cache = {}


def _get_data_uri(name: str) -> str:
    """Get base64 data URI for an icon by name."""
    if name not in _cache:
        svg = _SVGS[name]
        encoded = base64.b64encode(svg.encode()).decode()
        _cache[name] = f"data:image/svg+xml;base64,{encoded}"
    return _cache[name]


def icon_img(name: str, size: int = 22, margin_right: int = 6) -> str:
    """Generate an <img> tag for the given icon name.

    Args:
        name: Icon name (key in _SVGS dict)
        size: Width and height in pixels
        margin_right: Right margin in pixels

    Returns:
        HTML <img> tag string
    """
    uri = _get_data_uri(name)
    return (
        f'<img src="{uri}" width="{size}" height="{size}" '
        f'style="vertical-align: middle; margin-right: {margin_right}px;" alt="">'
    )
